import{_ as t,o,c as h,a2 as i}from"./chunks/framework.BBd5PKnH.js";const d=JSON.parse('{"title":"Moon (Mặt Trăng)","description":"","frontmatter":{},"headers":[],"relativePath":"astro/planets/moon.md","filePath":"astro/planets/moon.md"}'),a={name:"astro/planets/moon.md"};function g(r,n,s,c,l,u){return o(),h("div",null,[...n[0]||(n[0]=[i('<h1 id="moon-mat-trang" tabindex="-1">Moon (Mặt Trăng) <a class="header-anchor" href="#moon-mat-trang" aria-label="Permalink to &quot;Moon (Mặt Trăng)&quot;">​</a></h1><blockquote><p>Quy ước: <strong>[Sách]</strong> = nội dung có trong các trang bạn chụp. <strong>[Bổ sung]</strong> = kiến thức traditional astrology nói chung, mình thêm vào để nối với phần đã học. Phần [Bổ sung] nên đối chiếu lại với các chương sau của sách.</p></blockquote><hr><h2 id="_1-vi-tri-cua-moon-trong-he-thong" tabindex="-1">1. Vị trí của Moon trong hệ thống <a class="header-anchor" href="#_1-vi-tri-cua-moon-trong-he-thong" aria-label="Permalink to &quot;1. Vị trí của Moon trong hệ thống&quot;">​</a></h2><h3 id="nhom-two-lights-sach" tabindex="-1">Nhóm Two Lights [Sách] <a class="header-anchor" href="#nhom-two-lights-sach" aria-label="Permalink to &quot;Nhóm Two Lights [Sách]&quot;">​</a></h3><ul><li>Moon chiếu sáng ban đêm, điều chỉnh <strong>các tuần trong tháng</strong></li><li>Cùng Sun làm King/Queen: Moon = <strong>Queen / người mẹ</strong></li><li>5 hành tinh còn lại là &quot;bộ trưởng&quot; dưới quyền hai ánh sáng</li></ul><h3 id="moon-la-nguoi-đua-tin-sach-đoan-đa-hoc-truoc" tabindex="-1">Moon là &quot;người đưa tin&quot; [Sách, đoạn đã học trước] <a class="header-anchor" href="#moon-la-nguoi-đua-tin-sach-đoan-đa-hoc-truoc" aria-label="Permalink to &quot;Moon là &quot;người đưa tin&quot; [Sách, đoạn đã học trước]&quot;">​</a></h3><ul><li>Moon ở gần Trái Đất nhất và đi nhanh nhất, nên mỗi tháng <strong>gặp (hợp hoặc chiếu) tất cả hành tinh khác</strong></li><li>Nhờ đó Moon thu gom ảnh hưởng của các hành tinh rồi mang xuống thế giới vật chất</li><li>Vì vậy bảng 3 tầng vũ trụ có riêng một mục cho Moon: <strong>lunar applications, phases, nodes, eclipses</strong></li></ul><p><strong>Hiểu đơn giản:</strong> Moon giống người giao hàng. Trong lá số, muốn biết &quot;ảnh hưởng từ các hành tinh đến đời sống hằng ngày của người này thế nào&quot;, hãy xem Moon vừa gặp ai và sắp gặp ai.</p><hr><h2 id="_2-ban-chat-va-y-nghia-sach" tabindex="-1">2. Bản chất và ý nghĩa [Sách] <a class="header-anchor" href="#_2-ban-chat-va-y-nghia-sach" aria-label="Permalink to &quot;2. Bản chất và ý nghĩa [Sách]&quot;">​</a></h2><ul><li>Phản chiếu ánh sáng Sun xuống Trái Đất</li><li>Đại diện <strong>đời sống con người</strong>, <strong>toàn bộ thân thể</strong>, <strong>sự thụ thai</strong></li><li>Tính chất: <strong>ẩm, hơi ấm</strong></li></ul><table tabindex="0"><thead><tr><th>Nhóm</th><th>Nội dung</th></tr></thead><tbody><tr><td>Con người</td><td>Người mẹ, phụ nữ cai quản, bà chủ nhà, vú nuôi</td></tr><tr><td>Chủ đề</td><td>Hôn nhân hợp pháp, gia đình, thành phố, đám đông, du hành</td></tr><tr><td>Cơ thể</td><td>Mắt trái, dạ dày, ngực, lá lách, tủy xương</td></tr><tr><td>Vật chất</td><td>Bạc, thủy tinh</td></tr><tr><td>Màu / vị</td><td>Xanh lá / mặn</td></tr><tr><td>Ngày</td><td>Thứ Hai</td></tr></tbody></table><h3 id="than-thoai-va-ten-goi-sach" tabindex="-1">Thần thoại và tên gọi [Sách] <a class="header-anchor" href="#than-thoai-va-ten-goi-sach" aria-label="Permalink to &quot;Thần thoại và tên gọi [Sách]&quot;">​</a></h3><ul><li>Tên thơ ca: <em>Selēnē</em> (= ngọn lửa sáng, lấp lánh)</li><li>Sin (Babylon): người đo thời gian</li><li>Selēnē (Hy Lạp/La Mã): canh giấc ngủ người phàm → Artemis/Diana: nữ thợ săn trinh nữ của trăng non, giám hộ việc sinh nở</li></ul><h3 id="cot-loi-sach" tabindex="-1">Cốt lõi [Sách] <a class="header-anchor" href="#cot-loi-sach" aria-label="Permalink to &quot;Cốt lõi [Sách]&quot;">​</a></h3><ul><li>Bản chất (Valens): <strong>To nourish</strong>, essence: <strong>foresight</strong></li><li>Archetype hiện đại: <strong>The Caretaker</strong></li></ul><p><strong>Cách nhớ:</strong> Moon là &quot;cơ thể và nhịp sống&quot;. Mọi thứ thay đổi liên tục (đầy, vơi, ngày, đêm) đều mang dấu ấn Moon.</p><hr><h2 id="_3-essential-dignity-cua-moon-bo-sung" tabindex="-1">3. Essential dignity của Moon [Bổ sung] <a class="header-anchor" href="#_3-essential-dignity-cua-moon-bo-sung" aria-label="Permalink to &quot;3. Essential dignity của Moon [Bổ sung]&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Loại</th><th>Vị trí</th><th>Ý nghĩa dễ hiểu</th></tr></thead><tbody><tr><td>Domicile</td><td><strong>Cancer</strong></td><td>Nhà riêng, thoải mái nhất</td></tr><tr><td>Exaltation</td><td><strong>Taurus</strong> (nổi tiếng là khoảng 3°)</td><td>Được tôn vinh, ổn định và nuôi dưỡng</td></tr><tr><td>Triplicity</td><td>Nhóm <strong>đất</strong> (Taurus, Virgo, Capricorn), Moon cai quản <strong>ban đêm</strong></td><td>Có chỗ dựa vào ban đêm</td></tr><tr><td>Detriment</td><td><strong>Capricorn</strong></td><td>Đối diện nhà mình</td></tr><tr><td>Fall</td><td><strong>Scorpio</strong></td><td>Đối diện nơi được tôn vinh</td></tr></tbody></table><p><strong>Ví dụ cụ thể:</strong></p><ul><li>Moon ở Taurus: cảm xúc ổn định, thực tế, thích sự thoải mái và an toàn</li><li>Moon ở Scorpio (fall): cảm xúc dữ dội, khó thư giãn, khó cảm thấy &quot;an toàn&quot; một cách tự nhiên (mô tả mang tính truyền thống về condition, không phải phán xét tính cách)</li></ul><hr><h2 id="_4-sect-joy-phase-cua-moon-bo-sung" tabindex="-1">4. Sect, Joy, Phase của Moon [Bổ sung] <a class="header-anchor" href="#_4-sect-joy-phase-cua-moon-bo-sung" aria-label="Permalink to &quot;4. Sect, Joy, Phase của Moon [Bổ sung]&quot;">​</a></h2><ul><li><strong>Sect:</strong> Moon là ánh sáng của <strong>phe đêm</strong> (nocturnal). Lá số ban đêm, Moon in sect</li><li><strong>Joy:</strong> <strong>House 3</strong> (anh chị em, di chuyển ngắn, giao tiếp). Khớp với ý &quot;du hành&quot; và &quot;nhịp sống hằng ngày&quot;</li><li><strong>Phase của Moon (rất quan trọng với Moon):</strong><ul><li>Trăng <strong>đang tăng sáng</strong> (từ trăng non tới trăng tròn): được coi là có &quot;đà phát triển&quot;, nuôi dưỡng, mạnh hơn</li><li>Trăng <strong>đang giảm sáng</strong>: thu nhỏ, kết thúc, yếu hơn về mặt khả năng tăng trưởng</li><li>Moon <strong>rất sát Sun</strong> (trăng non): bị &quot;đốt&quot; ánh sáng, khó nhìn thấy</li></ul></li><li><strong>Tốc độ:</strong> Moon đi khoảng <strong>13 độ mỗi ngày</strong>, ở mỗi sign khoảng 2 đến 2.5 ngày. Moon đi nhanh hơn mức trung bình thì được coi là khỏe hơn</li><li><strong>Lunar applications:</strong> Moon <strong>sắp tạo aspect</strong> với hành tinh nào tiếp theo? Hành tinh đó cho biết &quot;chuyện gì sắp đến&quot; trong đời sống người này</li><li><strong>Void of course:</strong> Moon không tạo aspect nào nữa trước khi rời sign (kỹ thuật dùng nhiều trong chọn ngày giờ, xem lại chương sau)</li></ul><p><strong>Ví dụ dễ hình dung:</strong> trăng tăng sáng giống một người đang trên đà đi lên, năng lượng tăng dần. Trăng giảm sáng giống người đang dọn dẹp, đóng lại một chu kỳ, không phải &quot;xấu&quot; mà là hướng khác.</p><hr><h2 id="_5-moon-tot-vs-xau-đoc-nhu-the-nao" tabindex="-1">5. Moon tốt vs xấu: đọc như thế nào <a class="header-anchor" href="#_5-moon-tot-vs-xau-đoc-nhu-the-nao" aria-label="Permalink to &quot;5. Moon tốt vs xấu: đọc như thế nào&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Condition tốt</th><th>Condition xấu</th></tr></thead><tbody><tr><td>Ở Cancer/Taurus; lá số đêm; trăng tăng sáng; nhận aspect từ Jupiter/Venus; ở house mạnh (angular)</td><td>Ở Capricorn/Scorpio; bị Saturn/Mars chiếu căng; trăng sát Sun (ánh sáng yếu); ở house 6, 8, 12</td></tr><tr><td>Thường biểu hiện: thân thể ổn, đời sống thuận dòng, quan hệ với mẹ/phụ nữ tốt, thích nghi với thay đổi</td><td>Thường biểu hiện: đời sống nhiều xáo trộn, sức khỏe dễ dao động, quan hệ với mẹ/phụ nữ phức tạp, khó thích nghi</td></tr></tbody></table><p><strong>Insight:</strong> Moon liên quan đến <strong>đời sống thân xác hằng ngày</strong>. Nên khi Moon yếu, sách cổ thường đọc ra những dao động <em>thực tế</em> (sức khỏe, nơi ở, công việc thay đổi) chứ không chỉ là &quot;tâm trạng&quot; như cách hiểu hiện đại.</p><hr><h2 id="_6-khi-xem-la-so-cho-nguoi-khac-bo-sung" tabindex="-1">6. Khi xem lá số cho người khác [Bổ sung] <a class="header-anchor" href="#_6-khi-xem-la-so-cho-nguoi-khac-bo-sung" aria-label="Permalink to &quot;6. Khi xem lá số cho người khác [Bổ sung]&quot;">​</a></h2><h3 id="checklist-đanh-gia-moon" tabindex="-1">Checklist đánh giá Moon <a class="header-anchor" href="#checklist-đanh-gia-moon" aria-label="Permalink to &quot;Checklist đánh giá Moon&quot;">​</a></h3><ol><li>Lá số ngày hay đêm? (Moon in sect khi là đêm)</li><li>Moon ở sign nào? Có dignity gì?</li><li>Moon đang <strong>tăng</strong> hay <strong>giảm</strong> sáng? Cách Sun bao xa?</li><li>Moon ở house nào? Có phải house 3 (joy)? Hay angular?</li><li>Moon vừa rời aspect với ai, sắp tạo aspect với ai? Có benefic hay malefic nào chiếu?</li><li>Moon cai quản house nào (Cancer nằm ở house mấy)?</li></ol><h3 id="moon-noi-đuoc-gi-ve-nguoi-đo" tabindex="-1">Moon nói được gì về người đó <a class="header-anchor" href="#moon-noi-đuoc-gi-ve-nguoi-đo" aria-label="Permalink to &quot;Moon nói được gì về người đó&quot;">​</a></h3><ul><li><strong>Thân thể, sức khỏe nền tảng, nhịp sống hằng ngày</strong></li><li><strong>Mẹ, phụ nữ quan trọng trong đời</strong></li><li><strong>Nơi ở, gia đình, môi trường sống, di chuyển</strong></li><li><strong>Cách người này phản ứng với thay đổi</strong> (qua sign và phase)</li><li><strong>Sự kiện sắp diễn ra</strong> (qua lunar application)</li></ul><h3 id="cach-noi-voi-nguoi-đoi-dien-vi-du" tabindex="-1">Cách nói với người đối diện (ví dụ) <a class="header-anchor" href="#cach-noi-voi-nguoi-đoi-dien-vi-du" aria-label="Permalink to &quot;Cách nói với người đối diện (ví dụ)&quot;">​</a></h3><ul><li>Moon mạnh: &quot;Cơ thể và nhịp sống của bạn có khả năng tự điều chỉnh khá tốt. Khi mọi thứ xáo trộn, bạn thường lấy lại thăng bằng nhanh.&quot;</li><li>Moon yếu: &quot;Nhịp sống của bạn dễ bị xáo trộn hơn người khác, nên việc giữ một thói quen đều đặn (ngủ, ăn, chỗ ở ổn định) sẽ đặc biệt có ích.&quot;</li></ul><h3 id="luu-y" tabindex="-1">Lưu ý <a class="header-anchor" href="#luu-y" aria-label="Permalink to &quot;Lưu ý&quot;">​</a></h3><ul><li>Với sức khỏe, chỉ nói ở mức &quot;xu hướng, nên chú ý chăm sóc&quot;, <strong>không chẩn đoán</strong></li><li>Mẹ và phụ nữ trong đời: hỏi thực tế trước khi diễn giải</li><li>Moon di chuyển nhanh, nên <strong>giờ sinh sai vài chục phút</strong> cũng có thể đổi vị trí Moon và aspect. Nếu giờ sinh không chắc, hãy báo cho khách biết khi đọc Moon</li><li>Nhớ điều đã học: celestial condition giống nhau cho người sinh cùng ngày, <strong>trừ Moon</strong> (vì Moon đi quá nhanh)</li></ul><hr><h2 id="_7-loi-thuong-gap" tabindex="-1">7. Lỗi thường gặp <a class="header-anchor" href="#_7-loi-thuong-gap" aria-label="Permalink to &quot;7. Lỗi thường gặp&quot;">​</a></h2><ul><li>Đọc Moon chỉ như &quot;cảm xúc&quot; kiểu hiện đại. Truyền thống: <strong>thân thể, đời sống, mẹ, nơi ở, nhịp thay đổi</strong></li><li>Bỏ qua phase (tăng/giảm sáng) khi đánh giá Moon</li><li>Quên lunar application: Moon đang tiến tới ai quan trọng không kém Moon đang ở đâu</li></ul>',44)])])}const m=t(a,[["render",g]]);export{d as __pageData,m as default};
